#!/bin/sh
# Run the tests2 C23 cases on the cross backends and compare each against the
# expected output generated by the host gcc.
#
# Why this exists: two bugs (the arm64 bswap register field and _BitInt on
# targets where plain char is unsigned) passed every x86_64 check and every
# disassembly review, and only showed up when the output was actually
# executed.  Compiling for a target, or reading its disassembly, is not
# evidence that it works.
#
# Needs, per target: the cross compiler built by "make cross-<t>", qemu-user
# (binfmt registration is not required, the binary is run through it
# explicitly) and a target sysroot for libc.  Missing pieces are skipped.
#
# usage: tests/cross-run.sh [arm64 arm riscv64 ...]
set -u

src=$(cd "$(dirname "$0")/.." && pwd)
t2=$src/tests/tests2
out=$src/.bench/cross-run

# -B wants the directory that holds include/ and libtcc1.a, so the install
# tree is the natural choice; the target archive is passed explicitly because
# that tree only has the host one.
tccdir=${TCCDIR:-/opt/tinycc/lib/tcc}
if [ ! -d "$tccdir/include" ]; then
    # fall back to the source tree's own headers
    tccdir=$src
fi

# name:sysroot:qemu
targets=${*:-"arm64:/usr/aarch64-linux-gnu:qemu-aarch64
arm:/usr/arm-linux-gnueabihf:qemu-arm
riscv64:/usr/riscv64-linux-gnu:qemu-riscv64"}

tests="165_c23_spellings 168_c23_constexpr 172_c23_bitint
173_c23_fallthrough_place 174_c23_bitint_trunc 175_c23_bitint_incdec
176_c23_bitint_arith 177_c23_bitint_limits 178_c23_bitint_zero
179_c23_gnu_builtins 180_c23_builtin_object_size 181_c23_gnu_bit_builtins
182_c23_builtin_overflow 183_c23_has_c_attribute 184_c23_embed_params
185_c23_stdckdint 186_c23_bit_builtin_fold 187_c23_bitint_not_const
188_c23_bitint_var_width 189_c23_stddef_nullptr_t"

mkdir -p "$out" || exit 1
cd "$t2" || exit 1
pass=0; fail=0; skip=0; failed=""

for t in $targets; do
    name=${t%%:*}; rest=${t#*:}; sys=${rest%%:*}; qemu=${rest#*:}
    if [ ! -x "$src/$name-tcc" ]; then
        echo "skip $name: no $name-tcc (run make cross-$name)"; skip=$((skip+1)); continue
    fi
    if ! command -v "$qemu" >/dev/null; then
        echo "skip $name: $qemu not installed"; skip=$((skip+1)); continue
    fi
    if [ ! -d "$sys/include" ]; then
        echo "skip $name: no sysroot at $sys"; skip=$((skip+1)); continue
    fi
    lib=$src/$name-libtcc1.a
    [ -f "$lib" ] || lib=""
    # the target's own gcc is the right oracle when the expectation was
    # generated for a different word size
    triple=$(basename "$sys")
    xgcc=$triple-gcc
    command -v "$xgcc" >/dev/null || xgcc=""
    echo "===== $name ($sys${xgcc:+, oracle $xgcc}) ====="
    for n in $tests; do
        exe=$out/${n}_$name
        got=$out/${n}_$name.out
        exp=$n.expect
        [ -f "$exp" ] || continue
        rm -f "$exe" "$got"
        # keep the compiler's stderr: warnings are part of some expectations
        "$src/$name-tcc" -B"$tccdir" -I"$sys/include" -L"$sys/lib" -std=c23 \
            "$n.c" $lib -o "$exe" > "$got" 2>&1
        if [ -x "$exe" ]; then
            QEMU_LD_PREFIX=$sys "$qemu" "$exe" >> "$got" 2>&1
        fi
        if cmp -s "$exp" "$got"; then
            pass=$((pass+1))
            continue
        fi
        # A 32-bit target cannot match an expectation generated on a 64-bit
        # host, so fall back to that target's gcc before calling it a bug.
        if [ -n "$xgcc" ]; then
            gexe=$out/${n}_$name.gcc
            ggot=$out/${n}_$name.gccout
            rm -f "$gexe" "$ggot"
            "$xgcc" -w -std=c23 "$n.c" -o "$gexe" > "$ggot" 2>&1
            if [ -x "$gexe" ]; then
                QEMU_LD_PREFIX=$sys "$qemu" "$gexe" >> "$ggot" 2>&1
            fi
            if cmp -s "$ggot" "$got"; then
                pass=$((pass+1))
                echo "  $n: differs from the host expectation, matches $xgcc"
                continue
            fi
        fi
        fail=$((fail+1)); failed="$failed $name:$n"
        echo "  $n: output differs from $exp"
        diff -u "$exp" "$got" | sed -n '3,8p' | sed 's/^/    /'
    done
done

echo "----- pass=$pass fail=$fail skip=$skip -----"
if [ -n "$failed" ]; then
    echo "failed:$failed"
fi
[ $fail -eq 0 ]
